# Job-safe install for a Fabric JOB run. The pip-magic install cell CANCELS the
# session in a job run, so install with pip --target, prepend it to sys.path, and
# purge stale copies
# of lakelogic/pydantic that the base runtime pins older than lakelogic needs.
import subprocess, sys
_TARGET = "/tmp/lakelogic_libs"
subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "--target",
                       _TARGET, "lakelogic", "typing_extensions", "pyyaml"])
if _TARGET not in sys.path:
    sys.path.insert(0, _TARGET)
for _m in list(sys.modules):
    if _m.split(".")[0] in ("lakelogic", "pydantic", "pydantic_core", "typing_extensions"):
        del sys.modules[_m]

