# Parameters cell — the deploy/orchestration layer overrides these per (domain, system)
# run. Fabric injects ALL parameters as STRINGS; the numeric/boolean ones are coerced
# in the next cell.
lakehouse_name = "lakehouse"
domain = "lakehouse"
system = "lakehouse"
environment = "dev"                     # dev | staging | prod
engine = "spark"                        # spark | polars | duckdb
storage_mode = "catalog"                # catalog (schema-enabled lakehouse) | path
target_layers = "bronze, silver, gold"  # layers to process
entity_filter = ""                      # comma-separated entities to restrict to
reset_layers = ""                       # DROP these layers before processing
reload_layers = ""                      # TRUNCATE these layers before processing
dry_run = "false"                       # validate contracts, write nothing
ddl_only = "false"                      # create tables only, no data
retry_attempts = "1"                    # per-contract retries
retry_wait_sec = "30"                   # base wait between retries (seconds)
max_failures = "0"                      # stop after N consecutive failures (0 = unlimited)
resume_run = ""                         # resume a previous pipeline run id
created_by = ""                         # stamped into lineage metadata
landing_root_override = ""              # read bronze from THIS root instead of each
#                                         contract's source.path — a generic retarget so
#                                         the pipeline can run over an alternate landing
#                                         root (e.g. a staging copy) without editing contracts
synthetic_schema_prefix = ""            # prefix every output schema with this when
#                                         retargeting (keeps a retargeted estate in its own
#                                         `<prefix><domain>` schemas, never mixed with prod)

