# CELL ********************

import os
import traceback

# LakeLogic resolves {catalog} from FABRIC_<ENV>_LAKEHOUSE. On Fabric the catalog IS
# the attached schema-enabled lakehouse; contracts resolve {catalog}.{domain}.<table>.
os.environ[f"FABRIC_{environment.upper()}_LAKEHOUSE"] = lakehouse_name

REGISTRY_PATH = f"/lakehouse/default/Files/ll_contracts/{domain}/{system}/_system.yaml"
print(f"Registry: {REGISTRY_PATH}  (env: {environment})")

# Fabric passes parameters as strings — coerce the numeric/boolean ones.
DRY_RUN = str(dry_run).strip().lower() == "true"
DDL_ONLY = str(ddl_only).strip().lower() == "true"
RETRY_ATTEMPTS = int(str(retry_attempts).strip() or "1")
RETRY_WAIT = int(str(retry_wait_sec).strip() or "30")
MAX_FAILURES = int(str(max_failures).strip() or "0")

from lakelogic.core.registry import DomainRegistry
from lakelogic.pipeline import LakehousePipeline

registry = DomainRegistry.from_yaml(
    REGISTRY_PATH, environment=environment, storage_mode=storage_mode
)

# ── Landing-root retarget (optional) ────────────────────────────────────
# When landing_root_override is set, read each bronze contract's landing data from
# <override>/<source.path> instead of the real source.path — so this same pipeline can
# run bronze -> silver -> gold over an ALTERNATE landing root (e.g. a staging copy).
# synthetic_schema_prefix keeps the retargeted estate in its own `<prefix><domain>`
# schema(s), never mixed with production tables. Both fields are read by the engine as-is
# (bronze reads source['path']; output resolves to domain_catalog.<table>), so this is a
# pure retarget, not new runtime config.
_lro = str(landing_root_override).strip().strip('/')
_ssp = str(synthetic_schema_prefix).strip()
if _lro:
    for _c in registry.contracts:
        if _c.layer == 'bronze' and _c.contract_dict:
            _src = _c.contract_dict.get('source') or {}
            _p = _src.get('path')
            if _p and not str(_p).startswith(_lro + '/'):
                _src['path'] = f"{_lro}/{str(_p).lstrip('/')}"
                _c.contract_dict['source'] = _src
    print(f"Synthetic retarget: bronze landing <- {_lro}/<source.path>")
if _ssp:
    registry.storage.domain_catalog = f"{_ssp}{registry.storage.domain_catalog}"
    print(f"Synthetic retarget: output schema -> {registry.storage.domain_catalog}")

pipeline = LakehousePipeline(registry, engine=engine, spark=spark)  # noqa: F821 (Fabric global)

try:
    summary = pipeline.run(
        target_layers=target_layers,
        reset_layers=reset_layers,
        reload_layers=reload_layers,
        dry_run=DRY_RUN,
        entity_filter=entity_filter,
        environment=environment,
        retry_attempts=RETRY_ATTEMPTS,
        retry_base_wait_seconds=RETRY_WAIT,
        max_consecutive_failures=MAX_FAILURES,
        resume_from_run=resume_run or None,
        ddl_only=DDL_ONLY,
        created_by=created_by or None,
    )
except Exception:
    print(traceback.format_exc())
    raise

print("\n" + "=" * 70)
print("PIPELINE RUN SUMMARY")
print("=" * 70)
print(f"  Run : {summary.run_id}   Env : {summary.environment}")
for r in summary.results:
    print(f"  {r.get('contract','?'):<45} {r.get('layer','?'):<8} "
          f"{r.get('status','?'):<14} {r.get('rows','-')}")
    if r.get('error'):
        print(f"    -> {r['error']}")
print("=" * 70)

# Surface real per-contract errors so the Fabric pipeline activity fails loudly.
_failed = [r for r in summary.results if r.get('status') == 'failed']
if _failed:
    _details = ' | '.join(
        f"{r.get('contract') or r.get('table_name')} [{r.get('layer')}]: "
        f"{(str(r.get('error') or 'see logs').strip().splitlines() or ['see logs'])[0][:300]}"
        for r in _failed
    )
    raise RuntimeError(f"{len(_failed)} contract(s) failed — {_details}")

